SELECT customer_id AS customerId, SUM(CASE WHEN ledger_status IN (1, 2) THEN total_amount - paid_amount - discount_amount ELSE 0 END) AS debtAmount, SUM(CASE WHEN ledger_status = 4 THEN total_amount - paid_amount ELSE 0 END) AS creditAmount, COUNT(CASE WHEN ledger_status IN (1, 2) THEN 1 END) AS activeLedgerCount FROM ledger WHERE customer_id IN
#{id}
AND status = 1 GROUP BY customer_id
